SELECT CASE WHEN YEAR(stores.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(stores.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END opened_cohort, MAX(store_sales.units) max_units FROM store_sales INNER JOIN stores ON store_sales.store_id = stores.id WHERE MONTH(stores.opened_date) IN (4, 6, 11) GROUP BY CASE WHEN YEAR(stores.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(stores.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY max_units DESC;
